-- 0018_device_generation.sql — which trackers can even see 4G.
--
-- The fleet owner supplied the definitive list of 2G-only units (685 IMEIs,
-- mirrored in db/seed/device_2g_imei.txt); ANY IMEI NOT LISTED HERE IS 4G-CAPABLE.
-- That distinction is what makes the signal map honest: without it you cannot
-- tell "this area has no 4G" from "this truck could never report 4G anyway",
-- and 2G-only units drag down the average in places with fine 4G service.
--
-- Kept as a table (not a code constant) so hardware swaps are a one-line INSERT
-- rather than a redeploy.

CREATE TABLE IF NOT EXISTS device_generation (
  imei       text PRIMARY KEY,
  generation text NOT NULL CHECK (generation IN ('2g','4g'))
);

ON CONFLICT (imei) DO UPDATE SET generation = EXCLUDED.generation;

-- Per-cell 4G availability, counted ONLY from 4G-capable devices that actually
-- reported a Network Type reading. ratio = lte_on / lte_seen.
ALTER TABLE coverage_grid
  ADD COLUMN IF NOT EXISTS lte_seen bigint NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS lte_on   bigint NOT NULL DEFAULT 0;

-- Evidence-based correction. 528 of the 538 listed units seen in the week of
-- 2026-07-13 never emit a "Network Type" reading at all — the signature of 2G
-- hardware. These 10 emit one on 100% of pings and report LTE, which 2G radios
-- cannot do, so they are 4G units that were mislabelled in the supplied list.
-- (They are also the only entries carrying 8683730/8677470/8621290/8637380
-- prefixes rather than the 35xxxxx bulk.) Re-confirm against the asset register.
UPDATE device_generation SET generation = '4g' WHERE imei IN (
  '868373071323903','868373071803730','862129081287116','868373071358453',
  '867747079158695','868373075380966','867747076895968','863738070705968',
  '862129084797566','868373071822607'
);
